"""Load the predefined delivery locations into an empty table.

    uv run python -m order_service.seed

Run after `alembic upgrade head`. Safe to run again: if the table already has predefined locations, it's left alone.

seed/delivery-locations.csv has the columns Name, Description, Latitude, Longitude, and an optional Floor. Each row
goes through the same validation as an API request; a row that fails is logged and skipped rather than stored.
"""

import asyncio
import csv
import io
import logging
from pathlib import Path

from pydantic import ValidationError
from sqlalchemy import func, insert, select, text
from sqlalchemy.ext.asyncio import AsyncConnection

from order_service.config import get_settings
from order_service.db import create_engine
from order_service.schemas import DeliveryLocationCreate
from order_service.tables import delivery_locations

log = logging.getLogger(__name__)

# Any fixed number; stops two seed runs started at once from both inserting
SEED_LOCK_KEY = 3219_0004


def read_csv(path: Path) -> list[dict[str, str]]:
    content = path.read_bytes().decode("utf-8-sig")
    rows = csv.DictReader(io.StringIO(content))
    return [{k.strip(): (v or "").strip() for k, v in row.items() if k} for row in rows]


def delivery_location_from_row(row: dict[str, str]) -> DeliveryLocationCreate:
    return DeliveryLocationCreate(
        name=row["Name"],
        floor=row.get("Floor") or None,
        description=row.get("Description") or None,
        latitude=float(row["Latitude"]),
        longitude=float(row["Longitude"]),
    )


def load(path: Path) -> list[dict]:
    if not path.exists():
        log.warning("Seed file %s not found; skipping.", path)
        return []
    values = []
    for line_no, row in enumerate(read_csv(path), start=2):
        try:
            model = delivery_location_from_row(row)
        except (ValidationError, ValueError, KeyError) as exc:
            log.warning("Skipping %s line %d (%s): %s", path.name, line_no, row.get("Name"), exc)
            continue
        values.append(model.model_dump() | {"predefined": True})
    return values


async def seed_if_empty(conn: AsyncConnection, seed_dir: Path) -> None:
    await conn.execute(text("SELECT pg_advisory_xact_lock(:key)"), {"key": SEED_LOCK_KEY})

    predefined = await conn.scalar(
        select(func.count()).select_from(delivery_locations).where(delivery_locations.c.predefined)
    )
    if predefined:
        log.info("Predefined delivery locations already exist; not seeding them.")
        return
    rows = load(seed_dir / "delivery-locations.csv")
    if rows:
        await conn.execute(insert(delivery_locations), rows)
    log.info("Seeded %d delivery locations.", len(rows))


async def main() -> None:
    settings = get_settings()
    engine = create_engine(settings)
    try:
        async with engine.begin() as conn:
            await seed_if_empty(conn, settings.seed_dir)
    finally:
        await engine.dispose()


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO, format="%(levelname)s %(message)s")
    asyncio.run(main())
